from solution import is_happy
import pytest
from hypothesis import given, assume
import hypothesis.strategies as st


def reference(s):
    if len(s) < 3:
        return False
    for i in range(len(s) - 2):
        triple = s[i:i + 3]
        if len(set(triple)) != 3:
            return False
    return True


# ---- explicit spec examples ----
@pytest.mark.parametrize("s,expected", [
    ("a", False),
    ("aa", False),
    ("abcd", True),
    ("aabb", False),
    ("adb", True),
    ("xyy", False),
])
def test_spec_examples(s, expected):
    assert is_happy(s) is expected


def test_spec_example_single_char_is_false():
    assert is_happy("a") is False


def test_spec_example_two_chars_is_false():
    assert is_happy("aa") is False


def test_spec_example_abcd_is_true():
    assert is_happy("abcd") is True


def test_spec_example_aabb_is_false():
    assert is_happy("aabb") is False


def test_spec_example_adb_is_true():
    assert is_happy("adb") is True


def test_spec_example_xyy_is_false():
    assert is_happy("xyy") is False


# ---- boundaries ----
def test_empty_string_is_false():
    assert is_happy("") is False


def test_length_one_any_char_is_false():
    for c in ["a", "Z", "0", " ", "!"]:
        assert is_happy(c) is False


def test_length_two_any_pair_is_false():
    assert is_happy("ab") is False
    assert is_happy("aa") is False
    assert is_happy("ba") is False


def test_length_three_all_distinct_is_true():
    assert is_happy("abc") is True
    assert is_happy("adb") is True
    assert is_happy("xyz") is True


def test_length_three_with_any_repeat_is_false():
    assert is_happy("aaa") is False
    assert is_happy("aab") is False
    assert is_happy("aba") is False
    assert is_happy("abb") is False
    assert is_happy("baa") is False
    assert is_happy("bab") is False
    assert is_happy("bba") is False
    assert is_happy("xyy") is False


# ---- properties ----
@given(st.text(alphabet="abc", max_size=8))
def test_matches_reference_model_small_alphabet(s):
    assert is_happy(s) is reference(s)


@given(st.text(alphabet="abcdefXYZ012", max_size=12))
def test_matches_reference_model_larger_alphabet(s):
    assert is_happy(s) is reference(s)


@given(st.text(max_size=10))
def test_matches_reference_model_unicode(s):
    assert is_happy(s) is reference(s)


@given(st.text(max_size=10))
def test_short_strings_always_false(s):
    assume(len(s) < 3)
    assert is_happy(s) is False


@given(st.text(min_size=3, max_size=15))
def test_happy_implies_every_triple_distinct(s):
    assume(is_happy(s) is True)
    for i in range(len(s) - 2):
        a, b, c = s[i], s[i + 1], s[i + 2]
        assert a != b and a != c and b != c


@given(st.text(min_size=3, max_size=15))
def test_unhappy_implies_exists_repeated_triple(s):
    assume(is_happy(s) is False)
    assert any(
        len(set(s[i:i + 3])) < 3 for i in range(len(s) - 2)
    )


@given(st.text(alphabet="abcd", min_size=3, max_size=12))
def test_all_distinct_chars_implies_happy(s):
    assume(len(set(s)) == len(s))
    assert is_happy(s) is True


@given(st.integers(min_value=3, max_value=10))
def test_uniform_string_is_unhappy(n):
    assert is_happy("a" * n) is False
    assert is_happy("Z" * n) is False


@given(st.text(alphabet="ab", min_size=3, max_size=12))
def test_binary_alphabet_always_unhappy(s):
    # With only 2 distinct letters, any length>=3 window must repeat
    assert is_happy(s) is False


@given(st.text(min_size=3, max_size=12))
def test_substring_of_happy_is_happy_or_short(s):
    assume(is_happy(s) is True)
    # every contiguous substring of length >= 3 must itself be happy
    for lo in range(len(s)):
        for hi in range(lo + 3, len(s) + 1):
            sub = s[lo:hi]
            assert is_happy(sub) is True


@given(st.text(min_size=3, max_size=10), st.text(max_size=5), st.text(max_size=5))
def test_embedding_unhappy_preserves_unhappy(s, pre, post):
    assume(is_happy(s) is False)
    assert is_happy(pre + s + post) is False


@given(st.text(min_size=3, max_size=10))
def test_first_bad_triple_determines_result(s):
    # find first non-distinct triple; truncating just after it stays unhappy
    for i in range(len(s) - 2):
        if len(set(s[i:i + 3])) < 3:
            assert is_happy(s[:i + 3]) is False
            break


def test_alternating_two_chars_unhappy():
    # aba has first==third so unhappy; longer alternations contain it
    assert is_happy("aba") is False
    assert is_happy("abab") is False
    assert is_happy("ababa") is False
    assert is_happy("xyxyxy") is False


def test_returns_bool_type():
    assert is_happy("abcd") is True
    assert type(is_happy("abcd")) is bool
    assert is_happy("a") is False
    assert type(is_happy("a")) is bool
    assert is_happy("aabb") is False
    assert type(is_happy("aabb")) is bool
